// Copy tools/register.json, generated by tools/build-register.py, into public/tools/ so the
// development server and the build serve it at the path the site serves it from.
import { copyFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(here, "../../tools/register.json");
const target = resolve(here, "../public/tools/register.json");
mkdirSync(dirname(target), { recursive: true });
copyFileSync(source, target);
console.log(`register: ${source} -> ${target}`);
